	function onUse( _user, _targetTile )
	{
		local entity = this.Tactical.spawnEntity(this.m.Scripts.roll(), _targetTile.Coords.X, _targetTile.Coords.Y);
		entity.setFaction(::Const.Faction.Undead);

		//consume spirit
		this.m.Spirit = ::Math.max(0, this.m.Spirit - 50);
	}

	function findEmptyTile()
	{
		local actor = this.getContainer().getActor();
		if( actor == null || actor.isNull() ) return null;

		local tile = actor.getTile();
        if( tile == null ) return null;

        local possibleTiles = [];

		for( local i = 0; i != 6; ++i )
        {
            if (!tile.hasNextTile(i)) { continue; }
            local targetTile = tile.getNextTile(i);

            if ( targetTile.IsOccupiedByActor ) { continue; }

			possibleTiles.push(targetTile);

            //distance of 2
            for( local i = 0; i != 6; ++i )
            {
                if (!targetTile.hasNextTile(i)) { continue; }
                local targetTile2 = targetTile.getNextTile(i)

                if ( targetTile2.IsOccupiedByActor ) { continue; }

                possibleTiles.push(targetTile2);
            }
		}

new:
	function onUse( _user, _targetTile )
	{
		local entity = this.Tactical.spawnEntity(this.m.Scripts.roll(), _targetTile.Coords.X, _targetTile.Coords.Y);
		if (entity == null) return;
		entity.setFaction(_user != null ? _user.getFaction() : ::Const.Faction.Undead);
		entity.assignRandomEquipment();
		entity.riseFromGround();

		//consume spirit
		this.m.Spirit = ::Math.max(0, this.m.Spirit - 50);
	}

	function findEmptyTile()
	{
		local actor = this.getContainer().getActor();
		if( actor == null || actor.isNull() ) return null;

		local tile = actor.getTile();
        if( tile == null ) return null;

        local possibleTiles = [];

		for( local i = 0; i != 6; ++i )
        {
            if (!tile.hasNextTile(i)) { continue; }
            local targetTile = tile.getNextTile(i);

            if ( !targetTile.IsEmpty ) { continue; }

			possibleTiles.push(targetTile);

            //distance of 2
            for( local j = 0; j != 6; ++j )
            {
                if (!targetTile.hasNextTile(j)) { continue; }
                local targetTile2 = targetTile.getNextTile(j)

                if ( !targetTile2.IsEmpty ) { continue; }

                possibleTiles.push(targetTile2);
            }
		}
